import{az as a,P as n,Q as l,aQ as o}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const y=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"css/新特性/container.md","filePath":"css/新特性/container.md","lastUpdated":1785249401000}'),e={name:"css/新特性/container.md"};function p(t,s,c,r,i,D){return n(),l("div",null,[...s[0]||(s[0]=[o(`<h2 id="容器查询-container-queries" tabindex="-1">容器查询（Container Queries） <a class="header-anchor" href="#容器查询-container-queries" aria-label="Permalink to “容器查询（Container Queries）”">​</a></h2><blockquote><p>MDN 参考：<a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/CSS_container_queries" target="_blank" rel="noreferrer">https://developer.mozilla.org/zh-CN/docs/Web/CSS/CSS_container_queries</a></p></blockquote><p>容器查询是 CSS 近几年最重要的特性之一。它允许开发者根据<strong>父容器</strong>的尺寸来应用样式，而不是根据<strong>视口</strong>尺寸。这使得真正可复用的组件级响应式设计成为可能。</p><h3 id="一、为什么需要容器查询" tabindex="-1">一、为什么需要容器查询 <a class="header-anchor" href="#一、为什么需要容器查询" aria-label="Permalink to “一、为什么需要容器查询”">​</a></h3><p>传统响应式方案依赖 <code>@media</code> 媒体查询，它基于浏览器视口宽度断点。但实际开发中，组件可能被放置在不同宽度的容器中（侧边栏、主内容区、弹窗），即使视口相同，组件可用空间也截然不同。</p><p>容器查询解决了这一痛点：组件可以根据自身所在容器的实际大小自适应布局，真正做到&quot;一处编写，到处复用&quot;。</p><h3 id="二、container-type-定义容器" tabindex="-1">二、container-type 定义容器 <a class="header-anchor" href="#二、container-type-定义容器" aria-label="Permalink to “二、container-type 定义容器”">​</a></h3><p>使用 <code>container-type</code> 属性将一个元素声明为查询容器：</p><div class="language-css"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;">.</span><span style="color:#FFCB6B;">card-wrapper</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#B2CCD6;">  container-type</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> inline-size</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre></div><p>可选值：</p><ul><li><code>size</code>：同时在块轴和内联轴方向上建立查询容器，可查询容器的 <code>width</code> 和 <code>height</code>。</li><li><code>inline-size</code>：仅在内联轴（通常是宽度）方向上建立查询容器，最常用。</li><li><code>normal</code>：默认值，元素不作为尺寸查询容器，但仍可作为样式查询容器。</li></ul><h3 id="三、container-name-命名容器" tabindex="-1">三、container-name 命名容器 <a class="header-anchor" href="#三、container-name-命名容器" aria-label="Permalink to “三、container-name 命名容器”">​</a></h3><p>当一个页面中存在多个容器时，可以使用 <code>container-name</code> 为容器命名，避免查询混乱：</p><div class="language-css"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;">.</span><span style="color:#FFCB6B;">sidebar</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#B2CCD6;">  container-type</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> inline-size</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#B2CCD6;">  container-name</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> sidebar</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre></div><p>也可使用简写属性 <code>container</code>：</p><div class="language-css"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;">.</span><span style="color:#FFCB6B;">sidebar</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#B2CCD6;">  container</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> sidebar / inline-size</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre></div><h3 id="四、-container-语法" tabindex="-1">四、@container 语法 <a class="header-anchor" href="#四、-container-语法" aria-label="Permalink to “四、@container 语法”">​</a></h3><p><code>@container</code> 语法与 <code>@media</code> 类似，条件内可使用 <code>width</code>、<code>height</code>、<code>inline-size</code>、<code>block-size</code>、<code>aspect-ratio</code>、<code>orientation</code> 等尺寸特性：</p><div class="language-css"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;">.</span><span style="color:#FFCB6B;">card-wrapper</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#B2CCD6;">  container-type</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> inline-size</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;">.</span><span style="color:#FFCB6B;">card</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#B2CCD6;">  display</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> flex</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#B2CCD6;">  flex-direction</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> column</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;">/* 当容器内联尺寸大于 500px 时切换为横向布局 */</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">@container</span><span style="color:#BABED8;"> (min-width: 500px) </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#89DDFF;">  .</span><span style="color:#FFCB6B;">card</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#B2CCD6;">    flex-direction</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> row</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">  }</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;">/* 命名容器查询 */</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">@container</span><span style="color:#BABED8;"> sidebar (min-width: 300px) </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#89DDFF;">  .</span><span style="color:#FFCB6B;">widget</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#B2CCD6;">    font-size</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 16px</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">  }</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre></div><h3 id="五、与-media-的区别" tabindex="-1">五、与 @media 的区别 <a class="header-anchor" href="#五、与-media-的区别" aria-label="Permalink to “五、与 @media 的区别”">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>@media 媒体查询</th><th>@container 容器查询</th></tr></thead><tbody><tr><td>查询依据</td><td>浏览器视口尺寸</td><td>父容器尺寸</td></tr><tr><td>适用场景</td><td>页面整体布局</td><td>组件级响应式</td></tr><tr><td>组件复用性</td><td>差（依赖视口）</td><td>好（依赖容器）</td></tr><tr><td>上下文感知</td><td>否</td><td>是</td></tr></tbody></table><p>简单来说：<code>@media</code> 回答&quot;屏幕多宽&quot;，<code>@container</code> 回答&quot;我这个组件能放多大空间&quot;。</p><h3 id="六、实际应用场景" tabindex="-1">六、实际应用场景 <a class="header-anchor" href="#六、实际应用场景" aria-label="Permalink to “六、实际应用场景”">​</a></h3><ol><li><strong>卡片组件自适应</strong>：同一个卡片组件在侧边栏显示为纵向，在主区域显示为横向。</li><li><strong>可复用的通用组件库</strong>：组件不再依赖页面布局，放哪都能正确响应。</li><li><strong>动态布局</strong>：根据容器宽度切换 grid 列数。</li></ol><div class="language-html"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;">&lt;</span><span style="color:#F07178;">div</span><span style="color:#C792EA;"> class</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">layout</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">  &lt;</span><span style="color:#F07178;">aside</span><span style="color:#C792EA;"> class</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">sidebar</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">    &lt;</span><span style="color:#F07178;">div</span><span style="color:#C792EA;"> class</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">card</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">&gt;</span><span style="color:#BABED8;">...</span><span style="color:#89DDFF;">&lt;/</span><span style="color:#F07178;">div</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">  &lt;/</span><span style="color:#F07178;">aside</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">  &lt;</span><span style="color:#F07178;">main</span><span style="color:#C792EA;"> class</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">content</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">    &lt;</span><span style="color:#F07178;">div</span><span style="color:#C792EA;"> class</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">card</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">&gt;</span><span style="color:#BABED8;">...</span><span style="color:#89DDFF;">&lt;/</span><span style="color:#F07178;">div</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">  &lt;/</span><span style="color:#F07178;">main</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">&lt;/</span><span style="color:#F07178;">div</span><span style="color:#89DDFF;">&gt;</span></span></code></pre></div><div class="language-css"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;">.</span><span style="color:#FFCB6B;">sidebar</span><span style="color:#89DDFF;">,</span><span style="color:#89DDFF;"> .</span><span style="color:#FFCB6B;">content</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#B2CCD6;">  container-type</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> inline-size</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">@container</span><span style="color:#BABED8;"> (min-width: 400px) </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#89DDFF;">  .</span><span style="color:#FFCB6B;">card</span><span style="color:#89DDFF;"> {</span><span style="color:#B2CCD6;"> flex-direction</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> row</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre></div><h3 id="七、容器查询单位-cqw-cqh" tabindex="-1">七、容器查询单位 cqw / cqh <a class="header-anchor" href="#七、容器查询单位-cqw-cqh" aria-label="Permalink to “七、容器查询单位 cqw / cqh”">​</a></h3><p>容器查询还引入了一组新的长度单位：</p><ul><li><code>cqw</code> / <code>cqmin</code> / <code>cqmax</code>：容器宽度的 1%</li><li><code>cqh</code>：容器高度的 1%</li><li><code>cqi</code> / <code>cqb</code>：容器内联 / 块尺寸的 1%</li></ul><div class="language-css"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;">.</span><span style="color:#FFCB6B;">card-title</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#B2CCD6;">  font-size</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 5cqi</span><span style="color:#89DDFF;">;</span><span style="color:#676E95;font-style:italic;"> /* 标题大小随容器宽度变化 */</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre></div><h3 id="八、浏览器兼容性" tabindex="-1">八、浏览器兼容性 <a class="header-anchor" href="#八、浏览器兼容性" aria-label="Permalink to “八、浏览器兼容性”">​</a></h3><p>容器查询自 2023 年起在主流浏览器全面可用：</p><ul><li>Chrome / Edge：105+（2022 年 8 月）</li><li>Safari：16+（2022 年 9 月）</li><li>Firefox：110+（2023 年 2 月）</li></ul><p>容器查询单位（cqw 等）的兼容性与上述版本一致。对于需要兼容旧版本浏览器的项目，可借助 PostCSS 插件或回退到 <code>@media</code> 方案。</p>`,34)])])}const h=a(e,[["render",p]]);export{y as __pageData,h as default};
